style.css:
/* ==UserStyle==
@name           shiny glass ui
@namespace      coderlamoder
==/UserStyle== */

* {
  font-family: Poppins, Arial, sans-serif !important;
  border-radius: 14px !important;
}

body {
  background: linear-gradient(135deg, #dffaff, #f4f0ff, #e4fff0) !important;
}

button,
input,
textarea,
[role="button"] {
  background: linear-gradient(#ffffffcc, #eafaffaa) !important;
  border: 1px solid #ffffffdd !important;
  box-shadow:
    0 5px 15px #7899aa33,
    inset 0 1px #ffffff !important;
  backdrop-filter: blur(14px) !important;
  transition: .18s ease !important;
}

button:hover,
[role="button"]:hover {
  transform: translateY(-2px) scale(1.02) !important;
  box-shadow:
    0 9px 22px #7899aa44,
    inset 0 1px #ffffff !important;
}

button:active,
[role="button"]:active {
  transform: scale(.97) !important;
}

main,
section,
nav,
header,
aside {
  background: #ffffff55 !important;
  border: 1px solid #ffffffaa !important;
  box-shadow: 0 15px 40px #55778822, inset 0 1px #ffffff !important;
  backdrop-filter: blur(18px) !important;
}
